void TerrainResourceBehavior::xfer(Xfer *xfer)
{
	UpdateModule::xfer(xfer);
	Xfer::Version version(1, 2);
	*xfer == version;
	if (version.m_minimum >= 2) {
		*xfer == m_registered;
	}
	*xfer == m_sleepAfterRegister;
	*xfer == m_incomeScale;
	if (version.m_minimum >= 2)
		return;
	if (xfer->IsLoading())
		m_registered = (m_sleepAfterRegister == 0);
}

// ---- from Code/GameEngine/Source/GameLogic/Object/Behavior/TerrainResourceBehaviorLoadPostProcess.cpp

void TerrainResourceBehavior::loadPostProcess()
{
	UpdateModule::loadPostProcess();
	if (!m_registered) {
		setWakeFrame(m_object, UPDATE_SLEEP_NONE);
	}
}

